/* CORDON — unit skins (js/skins.js)
   Every unit sheet is stored in this one file, so there are no extra image files to upload.
   FUN group currently holds: Knights.  Pick a skin from UNIT SKINS on the menu; the choice is remembered and the page reloads once to apply it. */
(function () {
    'use strict';
    const REAL = [["uk", "UK"], ["france", "France"], ["india", "India"], ["usa", "USA"], ["nationalguard", "National Guard"], ["germany", "Germany"], ["spain", "Spain"], ["japan", "Japan"]], JOBS = [["hazmat", "Hazmat Crew"], ["scientist", "Lab Scientists"], ["firefighter", "Firefighters"], ["chef", "Chefs"], ["miner", "Miners"], ["builder", "Builders"], ["ranger", "Rangers"]], FUN = [["knight", "Knights"]];
    const SHEETS = {"uk": "data:image/png;base64,", "france": "data:image/png;base64,", "india": "data:image/png;base64,", "usa": "data:image/png;base64,", "nationalguard": "data:image/png;base64,", "germany": "data:image/png;base64,", "spain": "data:image/png;base64,", "japan": "data:image/png;base64,", "hazmat": "data:image/png;base64,", "scientist": "data:image/png;base64,", "firefighter": "data:image/png;base64,", "chef": "data:image/png;base64,", "miner": "data:image/png;base64,", "builder": "data:image/png;base64,", "ranger": "data:image/png;base64,", "knight": "data:image/png;base64,"};
    let cur = 'uk'; try { cur = localStorage.getItem('cordonSkin') || 'uk'; } catch (e) {}
    if (!SHEETS[cur]) cur = 'uk';
    window.CordonSkins = { current: cur, sheet() { return SHEETS[cur]; }, all: REAL.concat(JOBS, FUN) };
    const css = document.createElement('style');
    css.textContent = '#skin-overlay{position:fixed;inset:0;z-index:99999;background:rgba(8,12,24,.96);overflow-y:auto;padding:calc(env(safe-area-inset-top,0px) + 14px) 14px 24px;color:#dbe6ff;font-family:sans-serif}#skin-overlay h2{margin:4px 0 8px;font-size:16px;letter-spacing:2px;color:#9fb4d8}#skin-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(128px,1fr));gap:10px;margin-bottom:14px}.skin-card{background:#16223a;border:2px solid #2a3b5e;border-radius:10px;padding:8px 4px 6px;text-align:center;cursor:pointer}.skin-card.on{border-color:#4aa3ff;background:#1d3358}.skin-card b{display:block;margin-top:4px;font-size:12px}.skin-thumb{display:inline-block;width:56px;height:78px;image-rendering:pixelated;background-repeat:no-repeat;background-size:900px auto}#skin-close{display:block;margin:6px auto 0;padding:11px 34px;border:0;border-radius:8px;background:#2f7bff;color:#fff;font-weight:700;font-size:14px}';
    document.head.appendChild(css);
    function open() {
        const ov = document.createElement('div'); ov.id = 'skin-overlay';
        const group = (title, list) => {
            let h = '<h2>' + title + '</h2><div id="skin-grid">';
            list.forEach(([id, name]) => {
                const t = r => '<span class="skin-thumb" style="background-image:url(' + SHEETS[id] + ');background-position:-17px -' + (r * 90 + 6) + 'px"></span>';
                h += '<div class="skin-card' + (id === cur ? ' on' : '') + '" data-id="' + id + '">' + t(0) + t(4) + '<b>' + name + '</b></div>';
            });
            return h + '</div>';
        };
        ov.innerHTML = group('REAL WORLD', REAL) + group('JOBS', JOBS) + group('FUN', FUN) + '<button id="skin-close">BACK</button>';
        ov.onclick = e => {
            if (e.target.id === 'skin-close') { ov.remove(); return; }
            const c = e.target.closest('.skin-card'); if (!c) return;
            const id = c.dataset.id; ov.remove();
            if (id !== cur) { try { localStorage.setItem('cordonSkin', id); } catch (er) {} location.reload(); }
        };
        document.body.appendChild(ov);
    }
    function addButton() {
        const ref = document.getElementById('m-settings') || document.getElementById('m-howto');
        if (!ref || document.getElementById('m-skins')) return;
        const b = document.createElement('button'); b.id = 'm-skins'; b.className = ref.className; b.textContent = 'UNIT SKINS';
        b.addEventListener('click', open); ref.parentNode.insertBefore(b, ref.nextSibling);
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', addButton); else addButton();
})();
